import{_ as i,a0 as a,w as u,s as l,ao as s,I as n,x as e,a1 as r,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"戴文的Linux內核專題：20 配置內核 (16) | LCTT x X-CMD","titleTemplate":false,"description":"戴文的Linux內核專題：20 配置內核 (16) | LCTT (The Linux Kernel) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"戴文的Linux內核專題：20 配置內核 (16) | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"戴文的Linux內核專題：20 配置內核 (16) | LCTT (The Linux Kernel) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The Linux Kernel/20 The Linux Kernel--Configuring the Kernel Part 16","title":"戴文的Linux內核專題：20 配置內核 (16)","tag":"The Linux Kernel","desc":""},"relativePath":"The Linux Kernel/20 The Linux Kernel--Configuring the Kernel Part 16.md","filePath":"[post].md"}'),d={name:"The Linux Kernel/20 The Linux Kernel--Configuring the Kernel Part 16.md"};function T(m,t,P,g,S,x){const p=a("Link");return u(),l("div",null,[t[11]||(t[11]=s('<h1 id="戴文的linux內核專題-20-配置內核-16" tabindex="-1">戴文的Linux內核專題：20 配置內核 (16) <a class="header-anchor" href="#戴文的linux內核專題-20-配置內核-16" aria-label="Permalink to “戴文的Linux內核專題：20 配置內核 (16)”">​</a></h1><p><img src="http://www.linux.org/attachments/slide-jpg.587/" alt=""></p><p>歡迎來到下一篇Linux內核文章。在本篇裏，我們將討論輸入/輸出端口。</p><p>首先，PS/2鼠標和AT鍵盤需要&quot;i8042 PC Keyboard controller&quot;驅動。在USB之前，鼠標和鍵盤使用圓形端口的PS/2端口。AT鍵盤是一種84鍵使用AT端口的IBM鍵盤。AT端口有5針而PS/2口有六針。</p><p>使用COM口(有時也稱RS232串口)的輸入設備需要這個驅動(Serial port line discipline)。COM是一種串口，意味着每次傳輸一位。</p><p>TravelMate筆記本需要這個特殊的驅動來使用連接到QuickPort的鼠標(ct82c710 Aux port controller)。</p><p>對於PS/2 mice、AT keyboards 和 XT keyboards的並口適配器使用這個驅動(Parallel port keyboard adapter)。</p><p>&quot;PS/2 driver library&quot;用於PS/2鼠標和AT鍵盤。</p><p>可以啓用&quot;Raw access to serio ports&quot;來允許設備文件作為字符文件來使用。</p><p>下面，下面有一個用於&quot;Altera UP PS/2 controller&quot;的驅動。</p><p>PS/2複用同樣需要一個驅動(TQC PS/2 multiplexer)。</p><p>ARC FPGA平台對於PS/2控制器需要特殊的驅動(ARC PS/2 support)。</p><p>注意：我想要説清楚這篇文章中討論的PS/2控制器並不是Sony的PlayStation上的遊戲控制器。這篇文章討論的是6針鼠標/鍵盤端口。控制器是一種有PS/2端口的卡。</p><p>&quot;Gameport support&quot;提供對15針gameport的支持。gameport是一種曾經被很多遊戲設備使用直到USB端口的發明的15針口。</p><p>下一個驅動是在ISA或者PnP總線卡上的gameport驅動(Classic ISA and PnP gameport support)。ISA代表&quot;Industry Standard Architecture&quot;(工業標準架構)並且它是一種在PCI之前的並行總線標準。PnP代表&quot;Plug-and-Play&quot;(即插即用)並且他是一種在ISA之前的通用標準。</p><p>&quot;PDPI Lightning 4 gamecard support&quot;提供了一個有gameport的遊戲卡的專有驅動。</p><p>SoundBlaster Audigy卡是一種專有gameport卡(SB Live and Audigy gameport support)。</p><p>ForteMedia FM801 PCI音頻控制器在卡上有一個音頻控制器(ForteMedia FM801 gameport support)。這個驅動只支持gameport。</p><p>下一步，我們可以進入&quot;Character devices&quot;。字符設備以字符傳輸數據。</p><p>首先，可以啓用/禁用TTY(Enable TTY)。移除TTY會節約很多空間，但是許多終端和這類設備需要TTY。除非你知道你在做什麼，否則不要禁用TTY。</p><p>致我的粉絲：如果你知道一個禁用TTY的理由，你能在下面發表你的答案並與我們共享麼?謝謝！</p><p>下一步，可以啓用/禁用&quot;Virtual terminals&quot;(虛擬終端)。再説一次，這個可以節約很多空間，但是虛擬終端很重要。</p><p>下一個驅動支持字體映射和Unicode轉換(Enable character translations in console)。這用於轉換ASCII到Unicode。</p><p>虛擬終端可以用這個驅動作為系統控制台(Support for console on virtual terminal)。系統控制台管理着登陸和內核信息/警告。</p><p>虛擬終端必須通過控制台驅動與物理終端交互(Support for binding and unbinding console drivers)。在虛擬終端可用之前，控制台驅動必須被加載。當虛擬終端關閉後，控制台終端必須被卸載。</p><p>下一個驅動提供了對Unix98 PTY驅動的支持(Unix98 PTY support)。這是Unix98偽終端。</p><p>有趣的事實：Linux內核允許某個文件系統一次在很多地方被多次掛載。</p><p>接下來，可以支持&quot;Support multiple instances of devpts&quot;(譯註：允許多個&quot;devpts&quot;文件系統實例）。devpts文件系統用於偽終端的slave。</p><p>過時的PTY同樣可以啓用(Legacy (BSD) PTY support)。</p><p>可以設置最大數量的使用中的過時PTS(Maximum number of legacy PTY in use)。</p><p>下面的驅動可以用於提供對其他驅動不支持的串口的支持 (Non-standard serial port support)。</p><p>下面有一些用於特定板和卡的驅動。</p><p>這個驅動支持GSM MUX協議(GSM多路複用)(GSM MUX line discipline support (EXPERIMENTAL))。</p><p>下一個驅動啓用kmem設備文件(/dev/kmem virtual device support)。kmem通常用於內核調試。kmem可以用於讀取某些內核變量和狀態。</p><p>Stallion卡上面有許多串口Stallion multiport serial support)。這個驅動特別支持這塊卡。</p><p>下面，我們可以進入到串行設備驅動了。如前所述，串行設備每次傳輸一位。</p><p>第一個驅動用於標準串口支持(8250/16550 and compatible serial support)。</p><p>在這個驅動下，即插即用(Plug-and-Play)同樣存在於串口中(8250/16550 PNP device support)。</p><p>下面的驅動允許串口用於連接一個終端後作為控制台(Console on 8250/16550 and compatible serial port)。</p><p>一些UART控制器支持直接內存訪問(DMA support for 16550 compatible UART controllers)。UART代表的是&quot;Universal Asynchronous Receiver/Transmitter&quot;(通用異步收發)。UART控制器轉換串行到並行，反之亦然。</p><p>下一步，這個驅動提供了標準PCI串行設備支持(8250/16550 PCI device support)。</p><p>16位PCMCIA串行設備由這個驅動支持(8250/16550 PCMCIA device support)。記住，PCMCIA是一種通常使用於筆記本的PC卡。</p><p>可以設置最大數量支持的串口(Maximum number of 8250/16550 serial ports)，接着是在啓動中註冊的最大數量(Number of 8250/16550 serial ports to register at runtime)。</p><p>為了擴展像HUB6的串行能力，啓用這個驅動(Extended 8250/16550 serial driver options)。</p><p>一個特殊驅動用於支持多於4種的過時串口(Support more than 4 legacy serial ports)。</p><p>當啓用這個驅動後，可以共享串口中斷(Support for sharing serial interrupts)。</p><p>使用這個驅動可以自動檢測串口中斷請求(Autodetect IRQ on standard ports)。</p><p>RSA串口同樣也在Linux內核中支持(Support RSA serial ports)。RSA代表的是&quot;Remote Supervisor Adapter&quot;(遠程管理適配器)。RSA是一種IBM特定的硬件。</p><p>下面，有不同的供應商/設備特定驅動。</p><p>下面有一個使用printk輸出用户信息的TTY驅動(TTY driver to output user messages via printk)。printk(print kernel)是一種通常打印啓動信息的特殊軟件。任何由printk顯示的字符串通常在/var/log/messages文件裏。shell命令&quot;dmesg&quot;顯示所有被printk使用的字符串。</p><p>下面，我們可以啓用/禁用並口打印機的支持(Parallel printer support)。</p><p>接下來的驅動允許打印機作為一個控制台(Parallel printer support)。這意味着內核消息會被逐字地由打印機打印。通常地在這個系列中使用&quot;print&quot;(打印)這個單詞時，意味這將輸出信息到屏幕上。而這次，字面上的意思是將數據輸出在紙上。</p><p>以下的驅動使設備文件在/dev/parport/中(Support for user-space parallel port device drivers)。這使得一些進程可以訪問。</p><p>再説一次，Linux內核有許多特性和驅動，所以我們還會在下一篇文章中繼續討論更多的驅動。謝謝！</p><p>致粉絲：我們正在接近配置過程的終點。我有一張你們很多人想知道的內核話題列表。這些話題包含了安裝內核、管理模組、加入第三方驅動、還有許多其他有趣的建議和要求。</p><hr>',56)),n("p",null,[t[1]||(t[1]=e("via: ",-1)),r(p,{href:"http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-16.4835/"},{default:o(()=>[...t[0]||(t[0]=[e("http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-16.4835/",-1)])]),_:1})]),n("p",null,[t[4]||(t[4]=e("譯者：",-1)),r(p,{href:"https://github.com/geekpi"},{default:o(()=>[...t[2]||(t[2]=[e("geekpi",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),r(p,{href:"https://github.com/wxy"},{default:o(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[8]||(t[8]=e("本文由 ",-1)),r(p,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),r(p,{href:"http://linux.cn/"},{default:o(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const L=i(d,[["render",T]]);export{f as __pageData,L as default};
